#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

typedef long long ll;
const int OO = 1e9;

int n, k;
vector<int> arr;
vector<int> mem;

int solve(int x) {
    if (x >= n - 1) return 0; // Base case: if at or beyond the last index, no cost
    if (mem[x] != OO) return mem[x]; // Return cached result if available

    mem[x] = OO; // Initialize with a large value
    for (int i = 1; i <= k && (x + i) < n; i++) {
        // Update the minimum cost directly within the loop
        mem[x] = min(mem[x], solve(x + i) + std::abs(arr[x] - arr[x + i]));
    }

    return mem[x]; // Return the computed minimum cost
}

int main() {
    cin >> n >> k;
    arr.resize(n);
    mem.resize(n, OO); // Initialize memoization array
    for (int i = 0; i < n; i++) {
        cin >> arr[i]; // Input values into the array
    }
    cout << solve(0) << endl; // Start solving from index 0
    return 0;
}

